module soc_synth_top(clk, rst_n, rx, tx, sclk, mosi, miso, cs_n,
     gpio_in, gpio_out, gpio_oe);
  input clk, rst_n, rx, miso;
  input [9:0] gpio_in;
  output tx, sclk, mosi, cs_n;
  output [9:0] gpio_out, gpio_oe;
  wire clk, rst_n, rx, miso;
  wire [9:0] gpio_in;
  wire tx, sclk, mosi, cs_n;
  wire [9:0] gpio_out, gpio_oe;
  soc_soc_if_soc_interface_default dut(.soc_if_clk (clk), .soc_if_rx
       (rx), .soc_if_tx (tx), .soc_if_sclk (sclk), .soc_if_mosi (mosi),
       .soc_if_miso (miso), .soc_if_cs_n (cs_n), .soc_if_gpio_in
       (gpio_in), .soc_if_gpio_out (gpio_out), .soc_if_gpio_oe
       (gpio_oe), .soc_if_rst_n (rst_n));
endmodule

